  if (musicEnabled && audio) music.play(won ? 'win' : 'lose', () => { if (mode === 'end' && musicEnabled) music.play('menu'); });
  if (currentLevel.boss) { bossToneOff(); const bb = boss2.active ? boss2 : boss, name = boss2.active ? boss2.def.title : 'Beetle Tank', jeer = deathTaunt();
    ui.message.textContent = (jeer ? '“' + jeer + '” · ' : '') + 'The ' + name + ' won · ' + DIFF.label + ' · health ' + Math.ceil(bb.hp) + ' / ' + bb.max + ' · Checkpoint: the fight restarts at the arena'; ui.start.textContent = 'Retry fight'; }
  else { ui.message.textContent = (won ? 'Cleared' : 'Run ended') + ' · ' + BIOMES[currentLevel.biome || 'forest'].name + ' L' + (((currentLevel.id - 1) % 6) + 1) + ' ' + currentLevel.name + ' · ' + DIFF.label + ' · Score ' + score + ' · ' + Math.floor(distance) + ' m' + (best ? ' · New best!' : ''); ui.start.textContent = 'Retry level'; }
