const coreDot = new T.Sprite(new T.SpriteMaterial({map: weakTexture, depthWrite: false, fog: false})); coreDot.position.copy(tankLocal(.564, .425, 1.45)); coreDot.scale.set(.7, .7, 1); bossGroup.add(coreDot);
