    const name = S[(i * 2 + (side > 0 ? 1 : 0) + Math.floor(rnd() * 2)) % 4], h = 9 + rnd() * 5;
    const sp = makeSprite(name, h * aspectOf(name), {bottom: true, tint: B.tint});
