const lavaFloor = new T.Mesh(new T.PlaneGeometry(40, 60).rotateX(-Math.PI / 2), new T.MeshBasicMaterial({color: 0xff4a08, transparent: true, opacity: .85, fog: false, depthWrite: false}));
