          h.crack += dt; h.mesh.material.color.setRGB(1, 1 - h.crack * .5, 1 - h.crack * .5);
          if (h.crack > .6) {
            h.broken = true; h.mesh.material.map = spriteTexture('tundra/ice_hole'); h.mesh.material.needsUpdate = true; h.mesh.position.y = -1.2;
            trappedPit = h; h.hit = true; distance = h.d; currentSpeed = 0; grounded = false; jumpVel = -1; rollTime = rollInvuln = 0;
            damage(22, 'Fell through thin ice'); message('Freezing water · Space + A / D to climb out', 4); burst(me.clone().setY(.3), colors.cream, 14);
          }
