// ======================================================================
// V15: ENEMIES of Desert, Tundra, Volcano, Space and the Alien City
// ======================================================================
const kindDef = e => ENEMY_KINDS[e.kind] || ENEMY_KINDS[{moth: 'drone', beetle: 'crawler', turret: 'turret'}[e.type]] || {};
