const ngHp = () => (progressFor(difficultyKey).ngOn ? NG_PLUS.enemyHp : 1);
const sandMat = new T.MeshStandardMaterial({color: 0xd8b070, roughness: 1}), iceMat = new T.MeshStandardMaterial({color: 0xd8f0ff, roughness: .3}), emberMat = new T.MeshBasicMaterial({color: 0xff7a2a});
