    bolts.push({mesh, source: start.clone(), velocity: target.sub(start).normalize().multiplyScalar(DIFF.boltSpeed * 1.15), cause: v.cause || boss2.def.title + ' volley'}); tone(150, .14, .06); v.fired++;
