  b2Weak.forEach(w => { w.glow.visible = w.dot.visible = w.on && b2Art.visible; if (w.on) { w.glow.scale.setScalar(w.size * 3.2 * pulse); w.dot.scale.setScalar(w.size * 1.1 * pulse); } });
