  if (n > ui.taunt.textContent.length) { ui.taunt.textContent = boss2.tauntText.slice(0, n); const ch = boss2.tauntText[n - 1]; if (ch && ch !== ' ') tone(70 + Math.random() * 50 + (ch.charCodeAt(0) % 7) * 6, .05, .05); }
