  enemyCheck(key,id){this.start(key,id);this.clearTargets();distance=200;const out={};const kinds=Object.keys(ENEMY_KINDS).filter(k=>!['drone','crawler','turret'].includes(k));
    for(const k of kinds){const e=spawnKind(k,{d:225,x:0,shooter:true});targets.push(e);for(let i=0;i<90;i++){health=maxHealth;update(1/30);}out[k]={hp:+e.hp.toFixed(1),vis:e.mesh.visible,d:+e.d.toFixed(1)};for(let i=0;i<20&&e.hp>0;i++)strike(e,3,{melt:true});out[k].dead=e.hp<=0;this.clearTargets();distance=200;}
    return out;},
  weaponCheck(key){this.start(key,8);const pr=prog();const out={};for(const w of WEAPON_ORDER){if(!pr.weapons.includes(w))pr.weapons.push(w);weapon=w;this.clearTargets();distance=200;lateral=0;currentSpeed=0;held.clear();place(1);const e=spawnKind('crawler',{d:distance+9,x:0});e.hp=999;targets.push(e);update(1/30);update(1/30);
      const hp=e.hp;firing=true;cooldown=0;for(let i=0;i<45;i++){held.clear();e.d=distance+9;e.x=0;e.shellHp=0;const v=e.mesh.position.clone().project(camera);pointer.set(v.x,v.y);update(1/30);}firing=false;for(let i=0;i<40;i++){e.d=distance+9;update(1/30);}out[w]=+(hp-e.hp).toFixed(2);}
    return out;},
  shop(key){const pr=prog();pr.coins=5000;openQuartermaster(7);const before=pr.coins;for(const tab of ['armoury','upgrades','soldier','loadout']){qmTab=tab;renderQM();}
    qmTab='soldier';renderQM();ui.qmList.querySelector('.qm-act button:not(:disabled)')?.click();qmTab='armoury';renderQM();ui.qmList.querySelector('.qm-act button:not(:disabled)')?.click();
    return {spent:before-pr.coins,upgrades:{...pr.upgrades},weapons:[...pr.weapons],cards:ui.qmList.children.length};},
  setPieces(key){const out={};for(const id of [3,9,15,21,27,33]){this.start(key,id);const sp=currentLevel.setPiece;distance=sp.d-14;lateral=0;const n0=targets.length;let chase=false,impacts=0;
    for(let i=0;i<150;i++){health=maxHealth;held.clear();held.add('KeyW');update(1/30);if(hz.chase)chase=true;impacts=Math.max(impacts,hz.markers.length);}
    out[id]={type:sp.type,done:hz.setDone,spawned:targets.length-n0,chase,impacts,nest:targets.filter(e=>Math.abs(e.d-sp.d)<6).map(e=>e.kind).join('/')};}return out;},
  maxHealthCheck(key){const pr=prog();pr.upgrades.armour=3;pr.upgrades.belt=2;pr.upgrades.startShield=1;this.start(key,7);const r={maxHealth,health,charges,shield};pr.upgrades={};return r;},
  endingRun(key){this.start(key,36);elapsed=120;health=80;boss2.freeze=0;hideTaunt();boss2Damage(boss2.hp+1);let n=0;for(;n<900&&mode==='finish';n++)finishUpdate(1/30);return {mode,phase:ending.phase,n,cls:ui.ending.className,ng:prog().ng,finished:prog().finished};},
  step(dt){if(mode==='play')update(dt);else if(mode==='finish')finishUpdate(dt);},
  bot(key,id=1){this.start(key,id);let jumpAt=0;for(let t=0;t<700 && mode==='play';t+=1/30){held.clear();held.add('KeyW');const desired=botLane(Math.sin(t*1.2)*2.5);if(Math.abs(desired-lateral)>.12)held.add(desired>lateral?'KeyD':'KeyA');firing=true;if(!botAim())pointer.set(0,0);if(t>=jumpAt){if(grounded){grounded=false;jumpVel=trappedPit?10.5:JUMP_VELOCITY;}jumpAt=t+1.1;}update(1/30);}return this.state();},
  state(){return {mode,health,distance,elapsed,finish,difficultyKey,earnedDrops,damageEvents,pickups:pickups.map(p=>({key:p.key,d:p.d,lane:p.lane,expiresAt:p.expiresAt})),targets:targets.map(e=>({d:e.d,type:e.type,hp:e.hp,training:e.training})),diff:DIFF};},
  damage(n,source){recovery=rollInvuln=shield=0;damage(n,source,false,true);},
  collectHealth(){collectDrop('health');},
  groupTest(leaked){const a={groupId:'test',hp:0,d:100,x:0},b={...a};registerHealthGroup(a);registerHealthGroup(b);healthGroups.get('test').failed=leaked;completeHealthGroup(b);return earnedDrops;},
  render(){place(1);scene.updateMatrixWorld(true);renderer.render(scene,camera);},
  menu(){setMode('menu');},
  view(d){distance=d;lateral=0;jumpY=0;currentSpeed=0;updateTargets(0);updateFinishApproach();place(1);scene.updateMatrixWorld(true);renderer.render(scene,camera);drawWarningEdges();return gateMat.opacity;},
  waveView(frames=18){held.clear();distance=300;lateral=0;currentSpeed=0;pressureTimer=0;for(let k=0;k<frames;k++)update(1/30);place(1);scene.updateMatrixWorld(true);renderer.render(scene,camera);drawWarningEdges();return targets.filter(e=>e.enter!==undefined).map(e=>({type:e.type,enter:+e.enter.toFixed(2),range:+e.range.toFixed(1),y:+e.mesh.position.y.toFixed(2)}));},
  debugNear(){return targets.filter(e=>Math.abs(e.d-distance)<60).map(e=>({type:e.type,d:+e.d.toFixed(1),range:+e.range.toFixed(1),vis:e.mesh.visible,hp:e.hp,op:+e.art.material.opacity.toFixed(2),artVis:e.art.visible,pos:e.mesh.position.toArray().map(v=>+v.toFixed(1))}));},
  warnView(){distance=300;lateral=0;elapsed=10;announceWave(1);place(1);scene.updateMatrixWorld(true);renderer.render(scene,camera);drawWarningEdges();return incomingWave;},
  finishFrame(sec){distance=finish-.1;lateral=0;currentSpeed=6;update(1/30);const n=Math.round(sec*30);for(let i=0;i<n;i++)finishUpdate(1/30);scene.updateMatrixWorld(true);renderer.render(scene,camera);return {mode,finishT};},
  finishRun(){distance=finish-.1;currentSpeed=6;update(1/30);for(let i=0;i<120;i++)finishUpdate(1/30);return {mode,results:ui.resultsRows.textContent,stars:ui.resultsStars.querySelectorAll('.got').length,stats:{...runStats}};},
  advance(d){distance=d;updateTargets(0);},
